// Demo data removed - using real data or manual input only

// =============================================================================
// FastAPI Business Category Integration
// =============================================================================

/**
 * API endpoint for the Python FastAPI microservice.
 * Override via environment variable: BUSINESS_CATEGORY_API_URL
 * Default: https://reviewgen-e1i8.onrender.com
 */
define('BUSINESS_CATEGORY_API_URL', getenv('BUSINESS_CATEGORY_API_URL') ?: 'https://reviewgen-e1i8.onrender.com');
define('BUSINESS_CATEGORY_API_KEY', getenv('BUSINESS_CATEGORY_API_KEY') ?: 'your_secret_api_key_here');

/**
 * Calls the FastAPI microservice to resolve a business category from a Google review URL.
 *
 * Returns a structured context array:
 *   [
 *     'business_name'        => string|null,
 *     'raw_category'         => string|null,
 *     'normalized_category'  => string|null,   // Already normalized by Python
 *     'category_confidence'  => float,
 *     'category_source'      => string|null,
 *   ]
 *
 * Returns null if the service is unreachable, returns an error, or the
 * category cannot be determined. PHP must handle null gracefully.
 *
 * SECURITY: The $googleReviewUrl is validated by Python as well, but PHP
 * must never pass user-controllable API endpoint paths here.
 */
function fetchBusinessContext(string $googleReviewUrl): ?array {
    // Basic sanity check before making the network call
    if (empty($googleReviewUrl) || strlen($googleReviewUrl) > 2048) {
        return null;
    }
    $parsed = parse_url($googleReviewUrl);
    if (!$parsed || !isset($parsed['host'])) {
        return null;
    }
    $allowedHosts = ['g.page', 'www.google.com', 'google.com', 'maps.google.com'];
    if (!in_array(strtolower($parsed['host']), $allowedHosts, true)) {
        return null;
    }

    $endpoint = rtrim(BUSINESS_CATEGORY_API_URL, '/') . '/api/v1/business/category';
    $payload  = json_encode(['url' => $googleReviewUrl]);

    $headers = [
        'Content-Type: application/json',
        'Accept: application/json',
    ];
    $apiKey = BUSINESS_CATEGORY_API_KEY;
    if (!empty($apiKey)) {
        $headers[] = 'X-API-Key: ' . $apiKey;
    }

    $ch = curl_init($endpoint);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_POST           => true,
        CURLOPT_POSTFIELDS     => $payload,
        CURLOPT_HTTPHEADER     => $headers,
        CURLOPT_TIMEOUT        => 10,
        CURLOPT_CONNECTTIMEOUT => 4,
        CURLOPT_SSL_VERIFYPEER => false,
    ]);

    $response = curl_exec($ch);
    $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    $curlErr  = curl_error($ch);
    curl_close($ch);

    // Hard failures — service down, DNS failure, timeout
    if ($response === false || !empty($curlErr) || $httpCode === 0) {
        return null;
    }

    // Non-2xx responses (rate limited, server error, bad auth)
    if ($httpCode < 200 || $httpCode >= 300) {
        return null;
    }

    $data = json_decode($response, true);
    if (!is_array($data)) {
        return null;
    }

    // Python returned success=false (challenge, extraction failure, etc.)
    if (empty($data['success']) || !isset($data['data'])) {
        return null;
    }

    $d = $data['data'];

    // Build the structured context — sanitize every field
    return [
        'business_name'       => isset($d['business_name'])       ? htmlspecialchars(strip_tags((string)$d['business_name']),       ENT_QUOTES, 'UTF-8') : null,
        'raw_category'        => isset($d['raw_category'])         ? htmlspecialchars(strip_tags((string)$d['raw_category']),         ENT_QUOTES, 'UTF-8') : null,
        'normalized_category' => isset($d['normalized_category'])  ? htmlspecialchars(strip_tags((string)$d['normalized_category']),  ENT_QUOTES, 'UTF-8') : null,
        'category_confidence' => isset($d['category_confidence'])  ? (float)$d['category_confidence'] : 0.0,
        'category_source'     => isset($d['category_source'])      ? htmlspecialchars(strip_tags((string)$d['category_source']),      ENT_QUOTES, 'UTF-8') : null,
    ];
}

// Legacy thin wrapper kept for backward-compat with the old single-value callers.
// New code should use fetchBusinessContext() directly.
function fetchCategoryFromMicroservice(string $googleReviewUrl): ?string {
    $ctx = fetchBusinessContext($googleReviewUrl);
    if (!$ctx) {
        return null;
    }
    // Prefer raw_category for $googleCategoryMap lookups (more granular),
    // fall back to normalized_category.
    return $ctx['raw_category'] ?? $ctx['normalized_category'] ?? null;
}

// --- Google Category Scraper (No API Hack) ---

function scrapeGoogleCategoryHack($businessName) {
    $ch = curl_init();
    $searchUrl = "https://html.duckduckgo.com/html/?q=" . urlencode($businessName . " category");
    
    // --- BYPASS GUARD: Realistic Browser Headers ---
    $headers = [
        "Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8",
        "Accept-Language: en-US,en;q=0.9",
        "Upgrade-Insecure-Requests: 1"
    ];

    curl_setopt($ch, CURLOPT_URL, $searchUrl);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
    curl_setopt($ch, CURLOPT_FOLLOWLOCATION, 1); // Follow redirects
    curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
    curl_setopt($ch, CURLOPT_ENCODING, ""); // Handle gzip/deflate automatically
    curl_setopt($ch, CURLOPT_USERAGENT, 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36');
    
    // --- PRODUCTION READINESS: Prevent Hanging ---
    curl_setopt($ch, CURLOPT_TIMEOUT, 6); // Max 6 seconds wait
    curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 3); // Max 3 seconds connection wait
    curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false); // Ignore SSL issues on shared hosting
    
    $html = curl_exec($ch);
    curl_close($ch);
    
    if ($html) {
        // --- ATTEMPT: Brute force search for known categories in DuckDuckGo snippets ---
        $commonCats = [
            'tour operator', 'travel agency', 'software training institute', 'restaurant', 'cafe', 
            'coffee shop', 'plumber', 'electrician', 'hvac contractor', 'real estate agency', 
            'law firm', 'lawyer', 'accountant', 'dentist', 'dental clinic', 'doctor', 'hospital', 
            'gym', 'fitness center', 'yoga studio', 'hair salon', 'beauty salon', 'spa', 'car repair', 
            'auto repair shop', 'car wash', 'marketing agency', 'advertising agency', 'web designer', 
            'software development', 'web development', 'it services', 
            'software company', 'information technology', 'cleaning service', 'pest control', 
            'moving company', 'roofing contractor', 'painter', 'landscaper', 'bakery', 'hotel', 
            'insurance agency', 'event planner', 'photographer', 'caterer', 'florist', 'jeweler', 
            'boutique', 'clothing store', 'hardware store', 'furniture store', 'veterinarian'
        ];
        
        foreach ($commonCats as $cat) {
            if (preg_match("/\b" . preg_quote($cat, '/') . "\b/i", $html)) {
                return $cat;
            }
        }
    }
    return null; 
}

