        'furniture store' => 'Furniture & Home Decor',
        'veterinarian' => 'Pet Care & Veterinary',
        'pet groomer' => 'Pet Care & Veterinary',
        'towing service' => 'Auto Services',
        'auto body shop' => 'Auto Repair'
    ];

    // -------------------------------------------------------------------------
    // Step 1: Build $businessContext — the canonical source of category truth.
    // -------------------------------------------------------------------------
    // Default empty context. All fields are null/zero until populated.
    $businessContext = [
        'business_name'       => null,
        'raw_category'        => null,
        'normalized_category' => null,
        'category_confidence' => 0.0,
        'category_source'     => null,
    ];

    $originalServiceName = $serviceName; // Backup of whatever the frontend/DB sent
    $scrapedCategory     = null;
    $scraperSuccess      = false;

    // -------------------------------------------------------------------------
    // Step 2: Try FastAPI microservice first (most reliable — uses review URL).
    // -------------------------------------------------------------------------
    if ($googleReviewUrl) {
        $apiContext = fetchBusinessContext($googleReviewUrl);
        if ($apiContext) {
            $businessContext = $apiContext;
            $scrapedCategory = $apiContext['raw_category'] ?? $apiContext['normalized_category'];
        }
    }

    // -------------------------------------------------------------------------
    // Step 3: Fallback to the legacy name-based scraper if API was not used /
    //         returned nothing.
    // -------------------------------------------------------------------------
    if (!$scrapedCategory && $businessName) {
        $scrapedCategory = scrapeGoogleCategoryHack($businessName);
    }

    // -------------------------------------------------------------------------
    // Step 4: Resolve $serviceName for the review library.
    //
    // Priority A: If Python returned a normalized_category, try to match it
    //             directly in the SERVICE_REVIEW_LIBRARY (case-insensitive).
    //             This short-circuits the googleCategoryMap for API results.
    //
    // Priority B: Map via googleCategoryMap (handles raw/scraped categories).
    //
    // Priority C: Use the DB / dropdown service as-is.
    // -------------------------------------------------------------------------

    // Priority A — direct normalized_category → library key match
    $normalizedFromApi = $businessContext['normalized_category'] ?? null;
    if ($normalizedFromApi) {
        // Case-insensitive search for the key in the library
        foreach (array_keys($SERVICE_REVIEW_LIBRARY) as $libKey) {
            if (strcasecmp($libKey, $normalizedFromApi) === 0) {
                $serviceName    = $libKey;
                $scraperSuccess = true;
                break;
            }
        }
    }

    // Priority B — map raw/scraped category through the googleCategoryMap
    if (!$scraperSuccess && $scrapedCategory) {
        $normalizedInput = strtolower($scrapedCategory);
        if (array_key_exists($normalizedInput, $googleCategoryMap)) {
            $mappedService = $googleCategoryMap[$normalizedInput];
            if (isset($SERVICE_REVIEW_LIBRARY[$mappedService])) {
                $serviceName    = $mappedService;
                $scraperSuccess = true;
            }
        }
    }

    // Priority C — DB / dropdown service fallback
    if (!$scraperSuccess && $originalServiceName) {
        $normalizedInput = strtolower($originalServiceName);
        if (array_key_exists($normalizedInput, $googleCategoryMap)) {
            $mappedService = $googleCategoryMap[$normalizedInput];
            $serviceName   = isset($SERVICE_REVIEW_LIBRARY[$mappedService]) ? $mappedService : $originalServiceName;
        } else {
            $serviceName = $originalServiceName;
        }
    }
    
    if (!$serviceName || !isset($SERVICE_REVIEW_LIBRARY[$serviceName]) || !in_array($type, ['short', 'medium', 'long'])) {
        http_response_code(400);
        echo json_encode(['error' => 'Invalid service or review type']);
        exit;
    }
    
    $reviews = $SERVICE_REVIEW_LIBRARY[$serviceName][$type];
    
    if (empty($reviews)) {
        http_response_code(404);
        echo json_encode(['error' => 'No reviews found']);
        exit;
    }
    
    // Pick random review
    $randomReview = $reviews[array_rand($reviews)];
    
    echo json_encode([
        'review'              => $randomReview, 
        'service_used'        => $serviceName,
        'scraped_raw'         => $scrapedCategory,
        'scraper_success'     => $scraperSuccess,
        'original_service'    => $originalServiceName,
        // Business context from FastAPI (null fields if service was unavailable)
        'business_name'       => $businessContext['business_name'],
        'normalized_category' => $businessContext['normalized_category'],
        'category_confidence' => $businessContext['category_confidence'],
        'category_source'     => $businessContext['category_source'],
    ]);
    exit;
}

// 3. Extract Services for the Dropdown
$servicesList = array_keys($SERVICE_REVIEW_LIBRARY);
sort($servicesList);

$defaultService = '';
if (isset($services) && $services != '') {
    $userServicesArr = array_map('trim', explode(',', $services));
    foreach ($userServicesArr as $us) {
        if (in_array($us, $servicesList)) {
            $defaultService = $us;
            break;
        }
    }
    if (empty($defaultService)) {
        foreach ($userServicesArr as $us) {
            foreach ($servicesList as $sl) {
                if (stripos($sl, $us) !== false || stripos($us, $sl) !== false) {
                    $defaultService = $sl;
                    break 2;
                }
            }
        }
    }
}
if (empty($defaultService)) {
    $defaultService = $servicesList[0]; // fallback
}
?>
<!DOCTYPE html>
<html lang="en">
