</head>
<body class="bg-slate-50 min-h-screen p-4 sm:p-8 relative">

<!-- Toast Notification Container -->
<div id="toastContainer" class="fixed bottom-4 left-1/2 -translate-x-1/2 z-50 flex flex-col gap-2 pointer-events-none"></div>

<div class="max-w-4xl mx-auto space-y-8">
    
    <!-- Header -->
    <div class="text-center animate-fade-in-up">
        <h1 class="text-3xl font-bold tracking-tight text-slate-900">Review Generator</h1>
        <?php if (isset($db_error)): ?>
            <div class="bg-red-50 border border-red-200 rounded-xl p-4 mb-6 shadow-sm">
                <p class="text-sm font-bold text-red-800"><i class="fa-solid fa-triangle-exclamation mr-2"></i> Database Error</p>
                <p class="text-xs text-red-600 mt-1"><?= $db_error ?></p>
            </div>
        <?php endif; ?>
        
        <p class="text-slate-500 mt-2">Select a business card below to begin generating your review.</p>
    </div>

    <!-- Step 1: Business Cards -->
    <div class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4" id="cardsContainer">
        <?php foreach ($BUSINESS_CARDS as $card): ?>
            <div 
                class="business-card bg-white border border-slate-200 rounded-xl shadow-sm p-5 cursor-pointer hover:-translate-y-1 hover:border-indigo-500 hover:shadow-lg transition-all duration-300"
                data-name="<?= htmlspecialchars($card['company_name']) ?>"
                data-url="<?= htmlspecialchars($card['google_review_url']) ?>"
                data-services="<?= htmlspecialchars(isset($card['services']) ? $card['services'] : '') ?>"
            >
                <div class="flex items-center gap-3">
                    <div class="w-10 h-10 bg-indigo-50 rounded-full flex items-center justify-center shrink-0 border border-indigo-100">
                        <i class="fa-solid <?= htmlspecialchars($card['icon']) ?> text-indigo-600"></i>
                    </div>
                    <div>
                        <h3 class="font-bold text-slate-800 text-sm leading-tight"><?= htmlspecialchars($card['company_name']) ?></h3>
                        <p class="text-xs text-slate-400 mt-1 transition-colors group-hover:text-indigo-500">Click to select</p>
                    </div>
                </div>
            </div>
        <?php endforeach; ?>
    </div>

    <!-- Step 2: Generator -->
    <div id="generatorSection" class="hidden space-y-6 max-w-3xl mx-auto">
        
        <div class="bg-indigo-50/80 border border-indigo-200 rounded-xl p-4 flex justify-between items-center shadow-sm">
            <div>
                <p class="text-xs font-bold text-indigo-900/60 uppercase tracking-wider">Selected Business</p>
                <p id="selectedBusinessName" class="text-lg font-bold text-indigo-800 mt-0.5"></p>
            </div>
            <button id="changeBusinessBtn" class="text-sm font-semibold text-indigo-600 hover:text-indigo-800 hover:bg-indigo-100 px-3 py-1.5 rounded-lg transition-colors <?= $specific_user ? 'hidden' : '' ?>">Change</button>
        </div>

        <div class="bg-white border border-slate-200 rounded-xl shadow-sm p-6 space-y-6">
            
            <!-- Service Selector (Hidden for fully automatic) -->
            <div class="hidden">
                <label class="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Select a Service</label>
                <div class="relative">
                    <select id="serviceSelect" class="w-full pl-4 pr-10 py-3 text-sm font-medium border-2 border-slate-200 focus:border-indigo-500 focus:outline-none focus:ring-4 focus:ring-indigo-50 rounded-xl appearance-none bg-white transition-all cursor-pointer hover:border-slate-300">
                        <option value="" disabled selected>-- Select a category --</option>
                        <?php foreach ($servicesList as $service): ?>
                            <option value="<?= htmlspecialchars($service) ?>" <?= ($service === $defaultService) ? 'selected' : '' ?>><?= htmlspecialchars($service) ?></option>
                        <?php endforeach; ?>
                    </select>
                    <i class="fa-solid fa-chevron-down absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none text-sm"></i>
                </div>
            </div>

            <!-- Review Type Selector -->
            <div>
                <label class="block text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Review Length</label>
                <div class="flex gap-2 p-1 bg-slate-100 rounded-xl border border-slate-200/60">
                    <label class="flex-1 cursor-pointer relative">
                        <input type="radio" name="reviewType" value="short" class="peer sr-only" checked>
                        <div class="text-center px-4 py-2.5 rounded-lg peer-checked:bg-white peer-checked:shadow-sm peer-checked:text-indigo-700 font-semibold text-slate-500 text-sm hover:text-slate-700 transition-all">Short</div>
                    </label>
                    <label class="flex-1 cursor-pointer relative">
                        <input type="radio" name="reviewType" value="medium" class="peer sr-only">
                        <div class="text-center px-4 py-2.5 rounded-lg peer-checked:bg-white peer-checked:shadow-sm peer-checked:text-indigo-700 font-semibold text-slate-500 text-sm hover:text-slate-700 transition-all">Medium</div>
                    </label>
                    <label class="flex-1 cursor-pointer relative">
                        <input type="radio" name="reviewType" value="long" class="peer sr-only">
                        <div class="text-center px-4 py-2.5 rounded-lg peer-checked:bg-white peer-checked:shadow-sm peer-checked:text-indigo-700 font-semibold text-slate-500 text-sm hover:text-slate-700 transition-all">Long</div>
                    </label>
                </div>
            </div>

            <button id="generateBtn" class="relative group w-full bg-indigo-600 text-white py-3.5 px-4 rounded-xl shadow-md shadow-indigo-200 text-sm font-bold hover:bg-indigo-700 hover:shadow-lg hover:shadow-indigo-300 transition-all focus:ring-4 focus:ring-indigo-100 mt-2 overflow-hidden">
                <span id="btnText" class="relative z-10 flex items-center justify-center gap-2">
                    <i class="fa-solid fa-wand-magic-sparkles"></i> Generate Review
                </span>
            </button>
        </div>

        <!-- Review Display -->
        <div id="reviewDisplaySection" class="hidden bg-white border border-slate-200 rounded-xl shadow-sm p-6 space-y-5">
            <div class="flex justify-between items-center">
                <p class="text-xs font-bold text-slate-400 uppercase tracking-wider">Your Review</p>
                <button id="regenerateBtn" class="text-xs font-semibold text-indigo-600 hover:text-indigo-800 hover:bg-indigo-50 flex items-center gap-1.5 border border-slate-200 px-3 py-1.5 rounded-lg transition-colors shadow-sm">
                    <i class="fa-solid fa-rotate-right"></i> Re-Generate
                </button>
            </div>
            
            <div class="relative bg-slate-50 rounded-xl border border-slate-100 p-6 overflow-hidden">
                <i class="fa-solid fa-quote-left absolute top-4 left-4 text-4xl text-slate-200/50"></i>
                <p id="reviewOutput" class="relative z-10 text-slate-700 text-[15px] leading-relaxed whitespace-pre-wrap font-medium"></p>
            </div>
            
            <div class="pt-2">
                <button id="copyAndOpenBtn" class="w-full flex items-center justify-center gap-2.5 bg-indigo-600 hover:bg-indigo-700 text-white py-3.5 px-4 rounded-xl font-bold text-sm shadow-md shadow-indigo-200 transition-all focus:ring-4 focus:ring-indigo-100">
                    <i class="fa-solid fa-star text-yellow-300"></i>
                    Copy & Open Google Review
                    <i class="fa-solid fa-arrow-up-right-from-square text-white/70 ml-1"></i>
                </button>
                <p class="text-center text-xs text-slate-400 mt-3 font-medium">Review will copy to clipboard and open Google Maps automatically</p>
            </div>
        </div>

    </div>
</div>

<script>
document.addEventListener('DOMContentLoaded', () => {
    let currentGoogleUrl = <?= json_encode($specific_user ? (isset($specific_user['google_review_link']) ? $specific_user['google_review_link'] : '') : '') ?>;
    let currentBusinessName = <?= json_encode($specific_user ? ((isset($specific_user['company_name']) && $specific_user['company_name']) ? $specific_user['company_name'] : (trim((isset($specific_user['first_name']) ? $specific_user['first_name'] : '') . ' ' . (isset($specific_user['last_name']) ? $specific_user['last_name'] : '')))) : '') ?>;

    const validServices = <?= json_encode($servicesList) ?>;

    const cardsContainer = document.getElementById('cardsContainer');
    const generatorSection = document.getElementById('generatorSection');
    const selectedBusinessName = document.getElementById('selectedBusinessName');
    const changeBusinessBtn = document.getElementById('changeBusinessBtn');
    
    const serviceSelect = document.getElementById('serviceSelect');
    const generateBtn = document.getElementById('generateBtn');
    const btnText = document.getElementById('btnText');
    const regenerateBtn = document.getElementById('regenerateBtn');
    
    const reviewDisplaySection = document.getElementById('reviewDisplaySection');
    const reviewOutput = document.getElementById('reviewOutput');
    const copyAndOpenBtn = document.getElementById('copyAndOpenBtn');

    // Custom Toast Function
    function showToast(message, type = 'success') {
        const container = document.getElementById('toastContainer');
        const toast = document.createElement('div');
        const bgColor = type === 'success' ? 'bg-slate-800' : 'bg-red-600';
        toast.className = `toast-animate ${bgColor} text-white px-4 py-2.5 rounded-lg shadow-lg text-sm font-medium flex items-center gap-2 max-w-sm`;
        
        const icon = type === 'success' ? '<i class="fa-solid fa-check-circle text-green-400"></i>' : '<i class="fa-solid fa-triangle-exclamation text-white"></i>';
        toast.innerHTML = `${icon} ${message}`;
        
        container.appendChild(toast);
        setTimeout(() => {
            toast.style.opacity = '0';
            toast.style.transform = 'translateY(100%)';
            toast.style.transition = 'all 0.3s ease-in';
            setTimeout(() => toast.remove(), 300);
        }, 3000);
    }

    // Helper to decode HTML entities in JS
    function decodeHtml(html) {
        var txt = document.createElement("textarea");
        txt.innerHTML = html;
        return txt.value;
    }

    function getMatchedService(servicesStr) {
        if (!servicesStr) return validServices[0] || "";
        const arr = servicesStr.split(',').map(s => s.trim());
        for (let s of arr) {
            if (validServices.includes(s)) return s;
        }
        for (let s of arr) {
            for (let vs of validServices) {
                if (vs.toLowerCase().includes(s.toLowerCase()) || s.toLowerCase().includes(vs.toLowerCase())) {
                    return vs;
                }
            }
        }
        return validServices[0] || "";
    }

    // Prefill specific user details if passed
    if (currentBusinessName && currentGoogleUrl) {
        selectedBusinessName.textContent = currentBusinessName;
        cardsContainer.classList.add('hidden');
        generatorSection.classList.remove('hidden');
        
        // Ensure service dropdown has a value selected, fallback to first if empty
        if (!serviceSelect.value) {
            serviceSelect.value = decodeHtml(validServices[0]);
        }
        
        setTimeout(() => fetchReview(), 100);
    }

    // 1. Handle Card Selection
    document.querySelectorAll('.business-card').forEach(card => {
        card.addEventListener('click', () => {
            currentGoogleUrl = card.getAttribute('data-url');
            currentBusinessName = card.getAttribute('data-name');
            let cardServices = card.getAttribute('data-services');
            
            // Try to match the service and select it in the dropdown
            const matched = getMatchedService(cardServices);
            
            // Note: serviceSelect options have decoded values in the DOM
            // We set value using the raw text.
            serviceSelect.value = decodeHtml(matched);
            
            if (!serviceSelect.value) { // If still empty (e.g. no match found in DOM options)
                serviceSelect.selectedIndex = 1; // Pick the first actual service (index 0 is placeholder)
            }
            
            selectedBusinessName.textContent = currentBusinessName;
            cardsContainer.classList.add('hidden');
            generatorSection.classList.remove('hidden');
            setTimeout(() => fetchReview(), 100);
        });
    });

    // Handle Changing Business
    if (changeBusinessBtn) {
        changeBusinessBtn.addEventListener('click', () => {
            generatorSection.classList.add('hidden');
            reviewDisplaySection.classList.add('hidden');
            cardsContainer.classList.remove('hidden');
            serviceSelect.value = ""; // Reset form
        });
    }

    // 2. Fetch Review Logic
    const fetchReview = async () => {
        let serviceName = serviceSelect.value; // If empty, backend will Auto Detect using scraper
        
        const type = document.querySelector('input[name="reviewType"]:checked').value;

        const btnOriginalText = btnText.innerHTML;
        btnText.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Generating...';
        generateBtn.disabled = true;
        generateBtn.classList.add('opacity-80', 'cursor-not-allowed');

        try {
            // Robust URL construction
            const baseUrl = window.location.href.split('?')[0];
            const response = await fetch(`${baseUrl}?action=generate&service=${encodeURIComponent(serviceName)}&business_name=${encodeURIComponent(currentBusinessName)}&google_review_url=${encodeURIComponent(currentGoogleUrl)}&type=${type}&t=${Date.now()}`);
            const data = await response.json();

            if (data.review) {
                // Personalize with selected business name
                let text = data.review.replace(/\{company_name\}/g, currentBusinessName);
                reviewOutput.textContent = text;
                reviewDisplaySection.classList.remove('hidden');
                
                // Optional auto-copy feature
                if (navigator.clipboard) {
                    navigator.clipboard.writeText(text).catch(err => console.log('Auto-copy prevented by browser'));
                }
            } else {
                showToast(data.error || 'An error occurred.', 'error');
            }
        } catch (error) {
            console.error('Error fetching review:', error);
            showToast('Failed to load review.', 'error');
        } finally {
            btnText.innerHTML = btnOriginalText;
            generateBtn.disabled = false;
            generateBtn.classList.remove('opacity-80', 'cursor-not-allowed');
        }
    };

    // Bind generate buttons
    generateBtn.addEventListener('click', fetchReview);
    regenerateBtn.addEventListener('click', fetchReview);

    // 3. Handle Copy & Open Google Review
    copyAndOpenBtn.addEventListener('click', function() {
        const textToCopy = reviewOutput.textContent;
        const originalHtml = copyAndOpenBtn.innerHTML;
        
        
        // Copy to clipboard synchronously
        try {
            const textarea = document.createElement('textarea');
            textarea.value = textToCopy;
            textarea.style.position = 'fixed'; // Prevent scrolling
            document.body.appendChild(textarea);
            textarea.select();
            document.execCommand('copy');
            document.body.removeChild(textarea);
            
            showToast('Review copied to clipboard!', 'success');
        } catch (err) {
            showToast('Could not copy automatically. Please copy manually.', 'error');
        }
        
        // Open the URL synchronously to prevent browser popup blockers
        if (currentGoogleUrl) {
            let urlToOpen = currentGoogleUrl.trim();
            if (!urlToOpen.startsWith('http://') && !urlToOpen.startsWith('https://')) {
                urlToOpen = 'https://' + urlToOpen;
            }
            window.open(urlToOpen, '_blank', 'noopener,noreferrer');
        } else {
            showToast('No Google Maps URL configured for this business.', 'error');
            return;
        }
        
        // Visual feedback
        copyAndOpenBtn.innerHTML = '<i class="fa-solid fa-check text-white"></i> Copied & Opened...';
        
        setTimeout(() => {
            copyAndOpenBtn.innerHTML = originalHtml;
        }, 800);
    });
});
</script>
</body>
</html>
